/* ==========================================================================
   Typing Master 60s - Modern Dark Neon Theme
   ========================================================================== */

:root {
  --bg-primary: #0a0e17;
  --bg-secondary: #121826;
  --bg-card: rgba(22, 30, 49, 0.75);
  --border-color: rgba(99, 102, 241, 0.2);

  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-dim: #64748b;

  --neon-cyan: #00f0ff;
  --neon-cyan-glow: rgba(0, 240, 255, 0.4);
  --neon-purple: #8b5cf6;
  --neon-amber: #f59e0b;
  --neon-rose: #f43f5e;
  --neon-rose-glow: rgba(244, 63, 94, 0.45);

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Hiragino Kaku Gothic ProN', 'Noto Sans JP', sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Courier New', monospace;

  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-full: 9999px;

  --transition-base: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  margin: 0;
  padding: 0;
  min-height: 100vh;
  background-color: var(--bg-primary);
  background-image: 
    radial-gradient(circle at 15% 15%, rgba(139, 92, 246, 0.12) 0%, transparent 40%),
    radial-gradient(circle at 85% 85%, rgba(0, 240, 255, 0.1) 0%, transparent 45%),
    radial-gradient(circle at 50% 50%, rgba(15, 23, 42, 0.6) 0%, transparent 80%);
  color: var(--text-main);
  font-family: var(--font-sans);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
  user-select: none;
}

/* ==========================================================================
   App Layout
   ========================================================================== */

.app-container {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  padding: 1.5rem 1rem;
  max-width: 900px;
  margin: 0 auto;
  position: relative;
}

/* ==========================================================================
   Header Section
   ========================================================================== */

.header-panel {
  width: 100%;
  text-align: center;
  margin-bottom: 1rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.35rem;
}

.title-text {
  font-size: clamp(1.8rem, 4vw, 2.6rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, #ffffff 20%, var(--neon-cyan) 60%, var(--neon-purple) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  text-shadow: 0 4px 20px rgba(0, 240, 255, 0.25);
}

.subtitle-text {
  font-size: clamp(0.85rem, 2vw, 1rem);
  color: var(--text-muted);
  font-weight: 500;
  letter-spacing: 0.05em;
}

/* ==========================================================================
   Status & Gauge Bar
   ========================================================================== */

.status-bar {
  width: 100%;
  background: var(--bg-card);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.35);
  margin-bottom: 1.5rem;
}

.time-badge {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-family: var(--font-mono);
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--neon-cyan);
}

.time-gauge-bg {
  width: 100%;
  height: 10px;
  background: rgba(255, 255, 255, 0.08);
  border-radius: var(--radius-full);
  overflow: hidden;
  position: relative;
}

.time-gauge-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--neon-cyan), var(--neon-purple));
  border-radius: var(--radius-full);
  transition: width 1s linear;
  box-shadow: 0 0 12px var(--neon-cyan-glow);
}

.score-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.4rem 0.85rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: var(--radius-full);
  font-size: 0.9rem;
  color: var(--text-main);
  font-weight: 600;
}

.combo-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.35rem 0.85rem;
  background: linear-gradient(135deg, rgba(245, 158, 11, 0.15), rgba(244, 63, 94, 0.2));
  border: 1px solid rgba(245, 158, 11, 0.4);
  border-radius: var(--radius-full);
  color: var(--neon-amber);
  font-weight: 700;
  font-family: var(--font-mono);
  animation: pulse 1.8s infinite ease-in-out;
}

@keyframes pulse {
  0%, 100% {
    transform: scale(1);
    box-shadow: 0 0 0 0 rgba(245, 158, 11, 0.4);
  }
  50% {
    transform: scale(1.05);
    box-shadow: 0 0 12px 2px rgba(245, 158, 11, 0.25);
  }
}

/* ==========================================================================
   Game Main Area
   ========================================================================== */

.game-area {
  width: 100%;
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  position: relative;
  min-height: 280px;
}

.hidden-input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
  width: 1px;
  height: 1px;
  top: 0;
  left: 0;
  border: none;
  background: transparent;
  color: transparent;
}

/* ==========================================================================
   Typing Card & Word Presentation
   ========================================================================== */

.typing-card {
  width: 100%;
  background: var(--bg-card);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 2.25rem 1.5rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 1.25rem;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.1);
  transition: var(--transition-base);
  position: relative;
  cursor: pointer;
}

.typing-card:hover {
  border-color: rgba(0, 240, 255, 0.4);
}

.typing-card:focus-visible {
  outline: 2px solid var(--neon-cyan);
  outline-offset: 2px;
}

.kanji-text {
  font-size: clamp(2rem, 5vw, 3.2rem);
  font-weight: 700;
  color: #ffffff;
  letter-spacing: 0.05em;
  line-height: 1.2;
}

.hiragana-text {
  font-size: clamp(1rem, 2.5vw, 1.4rem);
  color: var(--neon-cyan);
  font-weight: 500;
  letter-spacing: 0.12em;
  opacity: 0.9;
}

.romaji-container {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 2px;
  font-family: var(--font-mono);
  font-size: clamp(1.4rem, 3.8vw, 2.2rem);
  font-weight: 700;
  padding: 0.6rem 1.2rem;
  background: rgba(10, 14, 23, 0.7);
  border-radius: var(--radius-md);
  border: 1px solid rgba(255, 255, 255, 0.08);
  min-height: 3.5rem;
}

.romaji-char {
  display: inline-block;
  transition: all 0.1s ease;
  padding: 0 1px;
}

.char-typed {
  color: var(--text-dim);
  opacity: 0.4;
  transform: scale(0.96);
}

.char-current {
  color: #ffffff;
  background: linear-gradient(180deg, transparent 75%, var(--neon-cyan) 75%);
  text-shadow: 0 0 10px var(--neon-cyan);
  animation: currentBlink 1s infinite alternate;
  font-weight: 800;
}

@keyframes currentBlink {
  0% { opacity: 0.85; }
  100% { opacity: 1; text-shadow: 0 0 16px var(--neon-cyan); }
}

.char-remaining {
  color: #cbd5e1;
}

.shake-anim {
  animation: shake 0.35s cubic-bezier(0.36, 0.07, 0.19, 0.97) both;
  border-color: var(--neon-rose) !important;
  box-shadow: 0 0 25px var(--neon-rose-glow) !important;
}

@keyframes shake {
  10%, 90% { transform: translate3d(-2px, 0, 0); }
  20%, 80% { transform: translate3d(4px, 0, 0); }
  30%, 50%, 70% { transform: translate3d(-6px, 0, 0); }
  40%, 60% { transform: translate3d(6px, 0, 0); }
}

.next-preview {
  margin-top: 1rem;
  font-size: 0.9rem;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

/* ==========================================================================
   Key Guide & Helpers
   ========================================================================== */

.key-guide-container {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0.75rem;
  margin-top: 1.25rem;
}

.key-guide-box {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 42px;
  height: 42px;
  padding: 0 0.85rem;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-bottom: 3px solid rgba(255, 255, 255, 0.3);
  border-radius: var(--radius-sm);
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--neon-cyan);
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.3);
}

.instruction-text {
  font-size: 0.85rem;
  color: var(--text-dim);
  text-align: center;
  margin-top: 0.75rem;
}

/* ==========================================================================
   Start Overlay & Button
   ========================================================================== */

.start-overlay {
  position: absolute;
  inset: 0;
  background: rgba(10, 14, 23, 0.88);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border-radius: var(--radius-lg);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1.25rem;
  z-index: 10;
  padding: 1.5rem;
  text-align: center;
}

.start-btn {
  padding: 1rem 2.8rem;
  font-size: 1.25rem;
  font-weight: 700;
  color: #0a0e17;
  background: linear-gradient(135deg, var(--neon-cyan), #38bdf8);
  border: none;
  border-radius: var(--radius-full);
  cursor: pointer;
  box-shadow: 0 0 30px var(--neon-cyan-glow);
  transition: var(--transition-base);
  outline: none;
  letter-spacing: 0.05em;
}

.start-btn:hover {
  transform: translateY(-2px) scale(1.03);
  box-shadow: 0 0 40px rgba(0, 240, 255, 0.6);
}

.start-btn:active {
  transform: translateY(1px) scale(0.98);
}

.start-btn:focus-visible {
  outline: 2px solid var(--neon-cyan);
  outline-offset: 3px;
  box-shadow: 0 0 0 3px rgba(0, 240, 255, 0.4), 0 0 30px var(--neon-cyan-glow);
}

/* ==========================================================================
   Modal & Results Screen
   ========================================================================== */

.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(5, 8, 15, 0.85);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  z-index: 100;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.result-card {
  width: 100%;
  max-width: 520px;
  background: var(--bg-secondary);
  border: 1px solid rgba(0, 240, 255, 0.35);
  border-radius: var(--radius-lg);
  padding: 2.2rem 1.8rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.5rem;
  box-shadow: 0 25px 60px rgba(0, 0, 0, 0.7), 0 0 40px rgba(0, 240, 255, 0.15);
  transform: translateY(0);
  animation: slideUp 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes slideUp {
  from { transform: translateY(24px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

.result-title {
  font-size: 1.8rem;
  font-weight: 800;
  text-align: center;
  background: linear-gradient(135deg, #fff, var(--neon-cyan));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.rank-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.5rem 1.5rem;
  background: linear-gradient(135deg, rgba(139, 92, 246, 0.25), rgba(0, 240, 255, 0.2));
  border: 1px solid var(--neon-cyan);
  border-radius: var(--radius-full);
  font-size: 1.15rem;
  font-weight: 800;
  color: var(--neon-cyan);
  box-shadow: 0 0 20px var(--neon-cyan-glow);
}

.result-hero-score {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 0.4rem;
  margin: 0.25rem 0;
}

.score-number {
  font-family: var(--font-mono);
  font-size: clamp(3.2rem, 8vw, 4.5rem);
  font-weight: 900;
  color: #ffffff;
  line-height: 1;
  text-shadow: 0 0 25px var(--neon-cyan-glow);
}

.score-unit {
  font-size: 1.1rem;
  color: var(--text-muted);
  font-weight: 600;
}

.stats-grid {
  width: 100%;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}

.stat-item {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: var(--radius-md);
  padding: 0.9rem 1rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
}

.stat-label {
  font-size: 0.8rem;
  color: var(--text-muted);
  font-weight: 500;
}

.stat-value {
  font-family: var(--font-mono);
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--text-main);
}

.restart-btn {
  width: 100%;
  padding: 0.95rem;
  font-size: 1.1rem;
  font-weight: 700;
  color: #0a0e17;
  background: linear-gradient(135deg, var(--neon-cyan), #38bdf8);
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  box-shadow: 0 0 25px var(--neon-cyan-glow);
  transition: var(--transition-base);
  margin-top: 0.5rem;
}

.restart-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 0 35px rgba(0, 240, 255, 0.5);
}

.restart-btn:active {
  transform: translateY(1px);
}

.restart-btn:focus-visible {
  outline: 2px solid var(--neon-cyan);
  outline-offset: 3px;
  box-shadow: 0 0 0 3px rgba(0, 240, 255, 0.4), 0 0 25px var(--neon-cyan-glow);
}

/* ==========================================================================
   Responsive Breakpoints
   ========================================================================== */

@media (max-width: 480px) {
  .app-container {
    padding: 1rem 0.75rem;
  }

  .status-bar {
    padding: 0.85rem;
  }

  .typing-card {
    padding: 1.5rem 1rem;
    gap: 1rem;
  }

  .romaji-container {
    padding: 0.4rem 0.6rem;
  }

  .stats-grid {
    grid-template-columns: 1fr;
    gap: 0.65rem;
  }

  .result-card {
    padding: 1.6rem 1.2rem;
  }
}

export type GameStatus = 'idle' | 'playing' | 'finished';

export type WordDifficulty = 'easy' | 'normal' | 'hard';

export type TypingRank =
  | '神速のタイピングマスター'
  | '超一流タイパー'
  | '一流タイパー'
  | '一人前タイパー'
  | '見習いタイパー'
  | '初心者タイパー'
  | '慎重派タイパー';

export interface TypingWord {
  id: number;
  kanji: string;
  hiragana: string;
  romaji: string;
  difficulty?: WordDifficulty;
}

export interface GameState {
  status: GameStatus;
  timeLeft: number;
  totalCharsTyped: number;
  correctChars: number;
  missCount: number;
  combo: number;
  maxCombo: number;
  currentWordIndex: number;
  currentCharIndex: number;
}

export interface ResultStats {
  totalChars: number;
  correctChars: number;
  missCount: number;
  accuracy: number;
  cpm: number;
  rank: TypingRank | string;
  maxCombo?: number;
}

export interface TypingDisplayProps {
  word: TypingWord | null | undefined;
  charIndex: number;
  isMiss: boolean;
}

export interface ResultModalProps {
  stats: ResultStats;
  onRestart: () => void;
}

import { TypingDisplayProps } from '../types';

const TypingDisplay = ({
  word,
  charIndex,
  isMiss
}: TypingDisplayProps) => {
  if (!word) {
    return (
      <div className="typing-card" aria-label="問題読み込み中">
        <div className="hiragana-text">...</div>
        <div className="kanji-text">問題を読み込み中</div>
        <div className="romaji-container">
          <span className="romaji-char char-remaining">...</span>
        </div>
      </div>
    );
  }

  const romajiChars = word.romaji ? word.romaji.split('') : [];
  const cardClassName = isMiss ? 'typing-card shake-anim' : 'typing-card';

  return (
    <div className={cardClassName} aria-live="polite">
      <div className="hiragana-text">{word.hiragana}</div>
      <div className="kanji-text">{word.kanji}</div>
      <div className="romaji-container">
        {romajiChars.map((char, index) => {
          let charClass = 'romaji-char char-remaining';
          const isCurrent = index === charIndex;

          if (index < charIndex) {
            charClass = 'romaji-char char-typed';
          } else if (isCurrent) {
            charClass = 'romaji-char char-current';
          }

          return (
            <span
              key={`${word.id ?? 'empty'}-${index}-${char}`}
              className={charClass}
              aria-current={isCurrent ? 'step' : undefined}
            >
              {char}
            </span>
          );
        })}
      </div>
    </div>
  );
};

export default TypingDisplay;

import { useEffect, useRef } from 'react';
import { ResultModalProps } from '../types';

const ResultModal = ({ stats, onRestart }: ResultModalProps) => {
  const restartButtonRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    restartButtonRef.current?.focus();
  }, []);

  const maxCombo = (stats as unknown as { maxCombo?: number }).maxCombo ?? 0;

  return (
    <div className="modal-overlay" role="dialog" aria-modal="true">
      <div className="result-card">
        <h2 className="result-title">タイムアップ！結果発表</h2>

        <div className="rank-badge">
          {stats.rank}
        </div>

        <div className="result-hero-score">
          <span className="score-number">{stats.correctChars}</span>
          <span className="score-unit">文字 打鍵</span>
        </div>

        <div className="stats-grid">
          <div className="stat-item">
            <span className="stat-label">正確率</span>
            <span className="stat-value">{stats.accuracy.toFixed(1)}%</span>
          </div>
          <div className="stat-item">
            <span className="stat-label">打鍵速度 (CPM)</span>
            <span className="stat-value">{stats.cpm} 文字/分</span>
          </div>
          <div className="stat-item">
            <span className="stat-label">総入力キー数</span>
            <span className="stat-value">{stats.totalChars} 打</span>
          </div>
          <div className="stat-item">
            <span className="stat-label">ミス打鍵数</span>
            <span className="stat-value">{stats.missCount} 回</span>
          </div>
          <div className="stat-item">
            <span className="stat-label">最大コンボ数</span>
            <span className="stat-value">{maxCombo}</span>
          </div>
        </div>

        <button
          ref={restartButtonRef}
          type="button"
          className="restart-btn"
          onClick={() => onRestart()}
        >
          もう一度チャレンジする
        </button>
      </div>
    </div>
  );
};

export default ResultModal;

import { useState, useEffect, useRef, useCallback } from 'react';
import { GameState, ResultStats, TypingWord } from './types';
import { WORD_LIST } from './wordData';
import TypingDisplay from './components/TypingDisplay';
import ResultModal from './components/ResultModal';
import './index.css';

const TOTAL_TIME = 60;

const calculateRank = (correctChars: number, accuracy: number): string => {
  if (accuracy < 70) return '慎重派タイパー';
  if (correctChars >= 380) return '神速のタイピングマスター';
  if (correctChars >= 300) return '超一流タイパー';
  if (correctChars >= 220) return '一流タイパー';
  if (correctChars >= 150) return '一人前タイパー';
  if (correctChars >= 80) return '見習いタイパー';
  return '初心者タイパー';
};

const shuffleArray = (array: TypingWord[]): TypingWord[] => {
  const shuffled = [...array];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
};

const App = () => {
  const [words, setWords] = useState<TypingWord[]>(() => shuffleArray(WORD_LIST));
  const [gameState, setGameState] = useState<GameState>({
    status: 'idle',
    timeLeft: TOTAL_TIME,
    totalCharsTyped: 0,
    correctChars: 0,
    missCount: 0,
    combo: 0,
    maxCombo: 0,
    currentWordIndex: 0,
    currentCharIndex: 0
  });

  const [isMiss, setIsMiss] = useState<boolean>(false);
  const [resultStats, setResultStats] = useState<ResultStats | null>(null);

  const inputRef = useRef<HTMLInputElement>(null);
  const missTimerRef = useRef<number | null>(null);

  // 打鍵ごとのリスナー再登録を防止するため最新の状態をRefで保持
  const stateRef = useRef({ gameState, words });
  useEffect(() => {
    stateRef.current = { gameState, words };
  }, [gameState, words]);

  const currentWord: TypingWord | undefined = words[gameState.currentWordIndex];
  const nextWord: TypingWord | undefined = words[(gameState.currentWordIndex + 1) % words.length];

  const focusInput = useCallback(() => {
    if (inputRef.current) {
      inputRef.current.focus();
    }
  }, []);

  const finishGame = useCallback(() => {
    setGameState((prev) => {
      const accuracy = prev.totalCharsTyped > 0
        ? (prev.correctChars / prev.totalCharsTyped) * 100
        : 0;
      const cpm = Math.round(prev.correctChars);
      const rank = calculateRank(prev.correctChars, accuracy);

      setResultStats({
        totalChars: prev.totalCharsTyped,
        correctChars: prev.correctChars,
        missCount: prev.missCount,
        accuracy,
        cpm,
        rank,
        maxCombo: prev.maxCombo
      });

      return {
        ...prev,
        status: 'finished',
        timeLeft: 0
      };
    });
  }, []);

  const startGame = useCallback(() => {
    const newShuffled = shuffleArray(WORD_LIST);
    setWords(newShuffled);
    setGameState({
      status: 'playing',
      timeLeft: TOTAL_TIME,
      totalCharsTyped: 0,
      correctChars: 0,
      missCount: 0,
      combo: 0,
      maxCombo: 0,
      currentWordIndex: 0,
      currentCharIndex: 0
    });
    setResultStats(null);
    setIsMiss(false);

    setTimeout(() => {
      focusInput();
    }, 50);
  }, [focusInput]);

  // タイマー管理
  useEffect(() => {
    if (gameState.status !== 'playing') return;

    const timer = setInterval(() => {
      setGameState((prev) => {
        if (prev.timeLeft <= 1) {
          clearInterval(timer);
          finishGame();
          return { ...prev, timeLeft: 0 };
        }
        return { ...prev, timeLeft: prev.timeLeft - 1 };
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [gameState.status, finishGame]);

  // キー入力処理
  const handleKeyProcess = useCallback((pressedChar: string) => {
    const { gameState: currentGameState, words: currentWords } = stateRef.current;
    if (currentGameState.status !== 'playing') return;

    const targetWord = currentWords[currentGameState.currentWordIndex];
    if (!targetWord) return;

    const expectedChar = targetWord.romaji[currentGameState.currentCharIndex];

    if (pressedChar.toLowerCase() === expectedChar.toLowerCase()) {
      const nextCharIndex = currentGameState.currentCharIndex + 1;
      const isWordCompleted = nextCharIndex >= targetWord.romaji.length;

      setGameState((prev) => {
        const nextCombo = prev.combo + 1;
        const nextMaxCombo = Math.max(prev.maxCombo, nextCombo);
        const nextWordIndex = isWordCompleted
          ? (prev.currentWordIndex + 1) % currentWords.length
          : prev.currentWordIndex;

        return {
          ...prev,
          totalCharsTyped: prev.totalCharsTyped + 1,
          correctChars: prev.correctChars + 1,
          combo: nextCombo,
          maxCombo: nextMaxCombo,
          currentWordIndex: nextWordIndex,
          currentCharIndex: isWordCompleted ? 0 : nextCharIndex
        };
      });
    } else {
      if (missTimerRef.current) {
        clearTimeout(missTimerRef.current);
      }
      setIsMiss(true);
      missTimerRef.current = window.setTimeout(() => {
        setIsMiss(false);
      }, 300);

      setGameState((prev) => ({
        ...prev,
        totalCharsTyped: prev.totalCharsTyped + 1,
        missCount: prev.missCount + 1,
        combo: 0
      }));
    }
  }, []);

  // キーボードイベントハンドラ（リスナーの毎打鍵再登録を防止）
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const currentStatus = stateRef.current.gameState.status;

      if (currentStatus === 'finished') {
        return;
      }

      if (currentStatus !== 'playing') {
        if (e.key === 'Enter' || e.code === 'Space') {
          if (currentStatus === 'idle') {
            e.preventDefault();
            startGame();
          }
        }
        return;
      }

      if (e.key === 'Tab' || e.key === 'Escape') return;

      if (e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
        e.preventDefault();
        handleKeyProcess(e.key);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [startGame, handleKeyProcess]);

  // モバイル用Inputの入力検知
  const handleMobileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (stateRef.current.gameState.status !== 'playing') {
      e.target.value = '';
      return;
    }

    const value = e.target.value;
    if (value.length > 0) {
      const lastChar = value.slice(-1);
      handleKeyProcess(lastChar);
      e.target.value = '';
    }
  };

  const handleContainerClick = () => {
    if (gameState.status === 'playing') {
      focusInput();
    }
  };

  const nextChar = currentWord ? currentWord.romaji[gameState.currentCharIndex] : '';
  const gaugePercent = (gameState.timeLeft / TOTAL_TIME) * 100;

  return (
    <div className="app-container" onClick={handleContainerClick}>
      <header className="header-panel">
        <h1 className="title-text">タイピングマスター 60</h1>
        <p className="subtitle-text">60秒で限界に挑むローマ字タイピング</p>
      </header>

      <section className="status-bar">
        <div className="time-badge">
          <span>残り時間</span>
          <span>{gameState.timeLeft} 秒</span>
        </div>
        <div className="time-gauge-bg">
          <div
            className="time-gauge-fill"
            style={{ width: `${Math.max(0, gaugePercent)}%` }}
          />
        </div>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div className="score-pill">
            <span>打鍵数:</span>
            <strong>{gameState.correctChars}</strong>
          </div>
          {gameState.combo > 2 && (
            <div className="combo-badge">
              <span>{gameState.combo} COMBO!</span>
            </div>
          )}
        </div>
      </section>

      <main className="game-area">
        {/* モバイルおよびフォーカス用不可視インプット */}
        <input
          ref={inputRef}
          type="text"
          className="hidden-input"
          onChange={handleMobileInput}
          disabled={gameState.status === 'finished'}
          autoComplete="off"
          autoCorrect="off"
          autoCapitalize="off"
          spellCheck={false}
          aria-label="タイピング入力"
        />

        {gameState.status === 'idle' && (
          <div className="start-overlay">
            <button
              type="button"
              className="start-btn"
              onClick={startGame}
            >
              スタート (Space)
            </button>
            <p className="instruction-text">
              スペースキーまたは画面タップでタイピング開始
            </p>
          </div>
        )}

        {currentWord && (
          <>
            <TypingDisplay
              word={currentWord}
              charIndex={gameState.currentCharIndex}
              isMiss={isMiss}
            />

            <div className="key-guide-container">
              <span className="key-guide-box">
                {nextChar.toUpperCase()}
              </span>
            </div>

            {nextWord && (
              <div className="next-preview">
                <span>次の問題:</span>
                <span>{nextWord.kanji}</span>
              </div>
            )}
          </>
        )}
      </main>

      <p className="instruction-text">
        ※ 入力が反応しない場合は、画面をタップしてキーボードをフォーカスしてください
      </p>

      {gameState.status === 'finished' && resultStats && (
        <ResultModal stats={resultStats} onRestart={startGame} />
      )}
    </div>
  );
};

export default App;
